{
 "quarter": "Q1 FY27",
 "callDate": "2026-07-30",
 "guidance": [
  {
   "metric": "branches",
   "statement": "Foresee 2,700 to 2,800 branches (maybe 3,000) for gold loans by year-end.",
   "quote": "By year-end we foresee 2,700 to 2,800 branches, all goes well, maybe 3,000 branches",
   "page": 4,
   "horizon": "FY27",
   "quantitative": true
  },
  {
   "metric": "orders",
   "statement": "Targeting INR 29,000 crores to INR 31,000 crores organic gold loan AUM by year-end.",
   "quote": "and AUM of between INR29,000 crores and INR31,000 crores, all organic.",
   "page": 4,
   "horizon": "FY27",
   "quantitative": true
  },
  {
   "metric": "margin",
   "statement": "Confident of delivering 25 to 40 basis points improvement in opex to NTI for FY27.",
   "quote": "Overall, we are confident of delivering 25 to 40 basis points improvement for FY '27 in opex to NTI.",
   "page": 4,
   "horizon": "FY27",
   "quantitative": true
  },
  {
   "metric": "volume",
   "statement": "Digital platform will deliver INR 50,000 crores of business this year and target INR 100,000 crores next year.",
   "quote": "I mean this year the digital platform will deliver INR50,000 crores of business. I am targeting that next year we should be delivering INR100,000 crores volume",
   "page": 6,
   "horizon": "FY27 and next year",
   "quantitative": true
  },
  {
   "metric": "volume",
   "statement": "AI, voice and text bots disbursements will reach INR 11,000 crores to INR 12,000 crores for the full year.",
   "quote": "On disbursements, AI, voice and text bots did INR2,500 crores, we will do INR11,000 crores INR12,000 in the full year this year.",
   "page": 6,
   "horizon": "FY27",
   "quantitative": true
  }
 ],
 "delivered": [
  {
   "metric": "other",
   "statement": "Added 5 million new customers during the quarter.",
   "page": 4
  },
  {
   "metric": "orders",
   "statement": "Added a record INR 37,000 crores of AUM in the quarter.",
   "page": 4
  },
  {
   "metric": "profit",
   "statement": "Profit growth was strong at 28%, with ROE crossing 20% (20.4%) and ROA at 4.7%.",
   "page": 4
  },
  {
   "metric": "margin",
   "statement": "Opex to NTI came in at 33.4%, marginally higher than last year.",
   "page": 4
  },
  {
   "metric": "orders",
   "statement": "Gold loan business grew by 112%, now forming 4% of AUM.",
   "page": 4
  },
  {
   "metric": "other",
   "statement": "Recognized additional macro provision of INR 296 crores; loan loss to AUF was 1.54%.",
   "page": 4
  }
 ],
 "tone": "confident on robust volume growth and improving credit metrics, maintaining careful balance sheet resilience.",
 "pushback": [
  {
   "topic": "Guidance Revision",
   "gist": "Analysts pressed why strong Q1 results and improving trends have not led to an upward revision in full-year guidance.",
   "page": 7
  },
  {
   "topic": "Capital Adequacy",
   "gist": "Questions raised on capital raising plans given high leverage and upcoming subsidiary dilution.",
   "page": 13
  },
  {
   "topic": "Gold Loan Competition",
   "gist": "Scepticism on intense competition in gold loans and potential cannibalization of personal loans.",
   "page": 16
  }
 ]
}
